/**
 * Read-only access to FogRules (SRD 5.2.1 data generated by tools/build-srd-data.mjs)
 */
(function (global) {
  'use strict';

  function rules() {
    return global.FogRules;
  }

  function getClass(id) {
    return (id && rules().classes[id]) || null;
  }

  function getSpecies(id) {
    return (id && id !== 'intro' && rules().species[id]) || null;
  }

  function getBackground(id) {
    return (id && id !== 'intro' && rules().backgrounds[id]) || null;
  }

  function getSpell(id) {
    return (id && rules().spells && rules().spells[id]) || null;
  }

  function getFeat(id) {
    return (id && rules().feats[id]) || null;
  }

  function getWeapon(id) {
    return (id && rules().weapons[id]) || null;
  }

  function getArmor(id) {
    return (id && rules().armor[id]) || null;
  }

  function getSkill(id) {
    return rules().skills.find(function (s) { return s.id === id; }) || null;
  }

  function getTool(id) {
    return rules().tools.find(function (t) { return t.id === id; }) || null;
  }

  function getLanguage(id) {
    var l = rules().languages;
    return l.standard.concat(l.rare).find(function (x) { return x.id === id; }) || null;
  }

  function listClasses() {
    return rules().meta.supportedClassIds.map(getClass);
  }

  function listSpecies() {
    return Object.keys(rules().species).filter(function (k) { return k !== 'intro'; }).map(getSpecies);
  }

  function listBackgrounds() {
    return Object.keys(rules().backgrounds).filter(function (k) { return k !== 'intro'; }).map(getBackground);
  }

  function listFeats(category) {
    return Object.values(rules().feats).filter(function (f) { return !category || f.category === category; });
  }

  function levelEntry(classId, level) {
    var cls = getClass(classId);
    return cls ? cls.levels[level] || null : null;
  }

  /** Proficiency bonus by character level (same for every class in the SRD tables). */
  function proficiencyBonus(level) {
    return Math.floor((level - 1) / 4) + 2;
  }

  function abilityModifier(score) {
    return Math.floor((score - 10) / 2);
  }

  function getSubclassLevel(classId) {
    var cls = getClass(classId);
    return cls ? cls.subclassLevel : 3;
  }

  /** Spell list of a class (or Druid, for Magic Initiate) at one spell level. */
  function spellIdsForList(listId, spellLevel) {
    var cls = getClass(listId);
    var list = cls && cls.spellList ? cls.spellList : (rules().extraSpellLists || {})[listId];
    if (!list) return [];
    return (list[spellLevel] || []).slice();
  }

  function spellsForClass(classId, spellLevel) {
    return spellIdsForList(classId, spellLevel).map(getSpell).filter(Boolean);
  }

  function isSpellcaster(classId) {
    var cls = getClass(classId);
    return !!(cls && cls.spellcasting);
  }

  /** Highest spell level for which a class has slots at a level (0 when none). */
  function maxSpellLevel(classId, level) {
    var entry = levelEntry(classId, level);
    if (!entry || !entry.slots) return 0;
    var max = 0;
    entry.slots.forEach(function (n, i) { if (n > 0) max = i + 1; });
    return max;
  }

  function hasFeature(classId, level, featureName) {
    var cls = getClass(classId);
    if (!cls) return false;
    return cls.features.some(function (f) { return f.name === featureName && f.level <= level; });
  }

  global.FogRulesApi = {
    rules: rules,
    getClass: getClass,
    getSpecies: getSpecies,
    getBackground: getBackground,
    getSpell: getSpell,
    getFeat: getFeat,
    getWeapon: getWeapon,
    getArmor: getArmor,
    getSkill: getSkill,
    getTool: getTool,
    getLanguage: getLanguage,
    listClasses: listClasses,
    listSpecies: listSpecies,
    listBackgrounds: listBackgrounds,
    listFeats: listFeats,
    levelEntry: levelEntry,
    proficiencyBonus: proficiencyBonus,
    abilityModifier: abilityModifier,
    getSubclassLevel: getSubclassLevel,
    spellIdsForList: spellIdsForList,
    spellsForClass: spellsForClass,
    isSpellcaster: isSpellcaster,
    maxSpellLevel: maxSpellLevel,
    hasFeature: hasFeature,
  };
})(window);
